    "title": "failover、恢复和 replay 必须区分证据与动作",
    "domain": "live_trading",
    "subdomain": "resilience_incident_log",
    "tree_node_id": "kt.live_execution.resilience_incident_log",
    "tree_path": "CEK-TA / Trading Engineering / Live Execution / Resilience Incident Log",
    "canonical_node_id": "kt.live_execution.resilience_incident_log",
    "canonical_tree_path": "CEK-TA / Trading Engineering / Live Execution / Resilience Incident Log",
