    "knowledge_id": "kb_phase45_stress_scenario.scenario_stress_test_required.v1",
    "title": "场景压力测试必须声明场景、假设和 owner",
    "domain": "risk_management",
    "subdomain": "scenario_stress_risk",
    "tree_node_id": "kt.risk_management.stress_scenario",
    "tree_path": "CEK-TA / Trading Engineering / Risk Management / Scenario Stress Risk",
    "canonical_node_id": "kt.risk_management.stress_scenario",
    "canonical_tree_path": "CEK-TA / Trading Engineering / Risk Management / Scenario Stress Risk",
