    "knowledge_id": "kb_phase59_market_microstructure.kline_microstructure_store_separation_required.v1",
    "title": "Kline snapshot 与 microstructure 高频数据不应默认混成一个物理宽表",
    "domain": "market_microstructure",
    "subdomain": "order_flow_storage_boundary",
    "tree_node_id": "kt.market_microstructure.order_flow",
    "tree_path": "CEK-TA / Trading Engineering / Market Microstructure / Order Flow",
    "canonical_node_id": "kt.market_microstructure.order_flow",
